import { MakeLogicType, actions, kea, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

import { MetricsMigrationReport } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface metricsMigrationLogicValues {
    live: boolean
    report: MetricsMigrationReport | null
    reportLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface metricsMigrationLogicActions {
    loadReport: () => any
    loadReportFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadReportSuccess: (
        report: MetricsMigrationReport | null,
        payload?: any
    ) => {
        report: MetricsMigrationReport | null
        payload?: any
    }
    setLive: (live: boolean) => {
        live: boolean
    }
}

export type metricsMigrationLogicType = MakeLogicType<metricsMigrationLogicValues, metricsMigrationLogicActions>

export const metricsMigrationLogic = kea<metricsMigrationLogicType>([
    path(['scenes', 'instance', 'SystemStatus', 'metricsMigrationLogic']),
    actions({
        setLive: (live: boolean) => ({ live }),
    }),
    reducers({
        live: [
            false,
            {
                setLive: (_, { live }) => live,
            },
        ],
    }),
    loaders(({ values }) => ({
        report: [
            null as MetricsMigrationReport | null,
            {
                loadReport: async (): Promise<MetricsMigrationReport | null> => {
                    const url = 'api/instance_status/metrics_migration' + (values.live ? '?live=true' : '')
                    const response = await api.get(url)
                    return response?.results ?? null
                },
            },
        ],
    })),
])
